-- Classifier accuracy audit.
CREATE TABLE "pulse_audit_cycles" (
	"id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
	"period" text NOT NULL,
	"surface" text DEFAULT 'cowork' NOT NULL,
	"sample_seed" bigint NOT NULL,
	"classifier_model" text,
	"rubric_version" integer,
	"stratum_weights" text,
	"status" text DEFAULT 'open' NOT NULL,
	"n_sampled" integer DEFAULT 0 NOT NULL,
	"n_reviewed" integer DEFAULT 0 NOT NULL,
	"agreement_pct" double precision,
	"kappa" double precision,
	"confusion_json" text,
	"created_at" bigint NOT NULL,
	"scored_at" bigint
);
--> statement-breakpoint
CREATE TABLE "pulse_audit_items" (
	"id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
	"cycle_id" integer NOT NULL,
	"classification_id" integer NOT NULL,
	"stratum" text NOT NULL,
	"model_tier" integer NOT NULL,
	"model_confidence" double precision,
	"human_tier" integer,
	"human_task_type" text,
	"reviewed_by" text,
	"reviewed_at" bigint,
	"agrees" integer
);
